-- 独立于费用/结算表，归还核验和风险只读菜单复用原交易目录。
ALTER TABLE admin_menu DROP CHECK ck_admin_menu_9, ADD CONSTRAINT ck_admin_menu_9 CHECK (permission_code IS NULL OR REGEXP_LIKE(permission_code, '^admin:[a-z0-9-]+:[a-z0-9-]+$','c') OR permission_code IN ('admin:trade:order:read','admin:trade:payment:read','admin:trade:refund:read','admin:trade:merchant:read','admin:trade:merchant:sync','admin:trade:transport:manage','admin:trade:operation:read','admin:fulfillment:return:read','admin:fulfillment:return:close','admin:fulfillment:risk:read'));
